(x, y, t) => {
  const cx = 240, cy = 120;
  const warpX = Math.sin(y * 0.02 + t * 0.3) * 15 + Math.cos(x * 0.015 - t * 0.2) * 10;
  const warpY = Math.sin(x * 0.018 - t * 0.25) * 12 + Math.cos(y * 0.022 + t * 0.35) * 8;
  const wx = x + warpX, wy = y + warpY;
  const src = [
    [160 + Math.sin(t * 0.6) * 100, 80 + Math.cos(t * 0.4) * 50, 0.08, 2.0],
    [320 + Math.cos(t * 0.5) * 100, 160 + Math.sin(t * 0.7) * 50, 0.1, 1.7],
    [240 + Math.sin(t * 0.3 + 2) * 140, 120 + Math.cos(t * 0.5 + 1) * 90, 0.06, 2.3],
    [120 + Math.cos(t * 0.8 + 4) * 80, 180 + Math.sin(t * 0.35 + 3) * 60, 0.12, 1.5],
    [360 + Math.sin(t * 0.45 + 1) * 90, 60 + Math.cos(t * 0.65 + 2) * 70, 0.07, 2.1]
  ];
  let act = 0, cross = 0;
  for (let i = 0; i < 5; i++) {
    const [sx, sy, fr, sp] = src[i];
    const d = Math.sqrt((wx - sx) ** 2 + (wy - sy) ** 2);
    act += Math.sin(d * fr - t * sp);
    if (i < 4) {
      const [sx2, sy2] = src[i + 1];
      const dm = Math.sqrt((wx - (sx + sx2) / 2) ** 2 + (wy - (sy + sy2) / 2) ** 2);
      cross += Math.sin(dm * (fr + 0.05) - t * (sp + 0.3)) * 0.3;
    }
  }
  act /= 5;
  const bg1 = Math.sin(wx * 0.05 + wy * 0.03 + t * 0.8);
  const bg2 = Math.sin(wx * 0.03 - wy * 0.05 + t * 1.1);
  const inh = (bg1 + bg2) / 2;
  const r1 = act - inh * 0.8 + Math.sin((wx + wy) * 0.15 + t * 3) * 0.15 + Math.sin((wx - wy) * 0.12 - t * 2.5) * 0.15 + cross;
  const s1 = Math.tanh(r1 * 2.5);
  const dist = Math.sqrt((wx - cx) ** 2 + (wy - cy) ** 2);
  const ang = Math.atan2(wy - cy, wx - cx);
  const pulse = 1 + Math.sin(t * 0.7) * 0.2;
  const p2 = Math.tanh((Math.sin(dist * 0.04 * pulse - t * 1.5) + Math.sin(ang * 6 + t * 0.4) * 0.5 + Math.sin(ang * 3 - dist * 0.02 + t * 1.2) * 0.3) * 2);
  const lg = Math.sin(wx * 0.015 + t * 0.3) * Math.cos(wy * 0.02 - t * 0.25);
  const r2 = Math.tanh((lg + Math.sin(dist * 0.02 - t * 0.8) + s1 * 0.3) * 1.5);
  const blend = s1 * 0.45 + p2 * 0.3 + r2 * 0.25;
  const v = blend * 0.5 + 0.5;
  const pal = [[8,15,58],[15,60,100],[25,120,140],[60,170,155],[180,195,80],[220,165,50],[200,85,55],[8,15,58]];
  const idx = v * (pal.length - 1), i = Math.min(idx | 0, pal.length - 2), f = idx - i;
  const lum = 0.82 + Math.sin(r1 * Math.PI) * 0.1 + Math.sin(r2 * Math.PI * 2) * 0.08;
  const edge = Math.abs(s1 - r2) * 0.3;
  return [
    Math.min(255, Math.max(0, (pal[i][0] + (pal[i+1][0] - pal[i][0]) * f) * lum + edge * 40)) | 0,
    Math.min(255, Math.max(0, (pal[i][1] + (pal[i+1][1] - pal[i][1]) * f) * lum + edge * 30)) | 0,
    Math.min(255, Math.max(0, (pal[i][2] + (pal[i+1][2] - pal[i][2]) * f) * lum + edge * 50)) | 0
  ];
}
